import com.betterstack.pulumi.EscalationPolicy;
import com.betterstack.pulumi.EscalationPolicyArgs;
import com.betterstack.pulumi.inputs.EscalationPolicyStepArgs;
import com.betterstack.pulumi.inputs.EscalationPolicyStepStepMemberArgs;
import com.betterstack.pulumi.IncidentsPrometheusIntegration;
import com.betterstack.pulumi.IncidentsPrometheusIntegrationArgs;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Map;
import java.io.File;
import java.nio.file.Files;
import java.nio.file.Paths;

public class App {
    public static void main(String[] args) {
        Pulumi.run(App::stack);
    }

    public static void stack(Context ctx) {
        var escalationPolicy = new EscalationPolicy("escalationPolicy", EscalationPolicyArgs.builder()
            .name("Standard Escalation Policy")
            .repeatCount(3)
            .repeatDelay(1800)
            .steps(            
                EscalationPolicyStepArgs.builder()
                    .type("escalation")
                    .waitBefore(0)
                    .severityId("$SEVERITY_ID")
                    .stepMembers(EscalationPolicyStepStepMemberArgs.builder()
                        .type("current_on_call")
                        .build())
                    .build(),
                EscalationPolicyStepArgs.builder()
                    .type("escalation")
                    .waitBefore(600)
                    .severityId("$SEVERITY_ID")
                    .stepMembers(EscalationPolicyStepStepMemberArgs.builder()
                        .type("entire_team")
                        .build())
                    .build())
            .build());

        var inEscalationPolicy = new IncidentsPrometheusIntegration("inEscalationPolicy", IncidentsPrometheusIntegrationArgs.builder()
            .name("Prometheus alerts")
            .sms(true)
            .teamWait(180)
            .escalationPolicyId(escalationPolicy.id())
            .build());

    }
}
```
