      steps:
        - type: escalation
          waitBefore: 0
          severityId: $SEVERITY_ID
          stepMembers:
            - type: current_on_call
        - type: escalation
          waitBefore: 600
          severityId: $SEVERITY_ID
          stepMembers:
            - type: entire_team
  inEscalationPolicy:
    type: betterstack:IncidentsPrometheusIntegration
